dashboard.definition:
{
	"dataSources": {
		"ds_WaZCTDkV": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` tag=dns message_type=\"QUERY\"\r\n| fields _time, src, query\r\n| streamstats current=f last(_time) as last_time by query\r\n| eval gap=last_time - _time\r\n| stats count dc(src) AS NumHosts avg(gap) AS AverageBeaconTime var(gap) AS VarianceBeaconTime BY query\r\n| eval AverageBeaconTime=round(AverageBeaconTime,3), VarianceBeaconTime=round(VarianceBeaconTime,3)\r\n| sort –count\r\n| where VarianceBeaconTime < 60 AND AverageBeaconTime > 0",
				"queryParameters": {
					"earliest": "1751371200",
					"latest": "1751479200"
				}
			},
			"name": "Bubble chart search 2"
		},
		"ds_yE9yBtpa": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` tag=dns message_type=\"QUERY\"\r\n| fields _time, query\r\n| streamstats current=f last(_time) as last_time by query\r\n| eval gap=last_time - _time\r\n| stats count avg(gap) AS AverageBeaconTime var(gap) AS VarianceBeaconTime BY query\r\n| eval AverageBeaconTime=round(AverageBeaconTime,3), VarianceBeaconTime=round(VarianceBeaconTime,3)\r\n| sort -count\r\n| where VarianceBeaconTime < 60 AND count > 2 AND AverageBeaconTime>1.000\r\n| table  query VarianceBeaconTime  count AverageBeaconTime",
				"queryParameters": {
					"earliest": "1751371200",
					"latest": "1751479200"
				}
			},
			"name": "Bubble chart search"
		},
		"ds_TsZBieYG": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` tag=dns message_type=\"QUERY\"\r\n| mvexpand query\r\n| eval queryLength=len(query)\r\n| stats count by queryLength, src\r\n| sort -queryLength, count\r\n| rename queryLength AS \"Query Length\"\r\n| rename count AS Volume\r\n| table src \"Query Length\" Volume\r\n| head 1000",
				"queryParameters": {
					"earliest": "1751371200",
					"latest": "1751479200"
				}
			},
			"name": "Scatter chart search"
		},
		"ds_pYyp9bI7": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` tag=dns message_type=\"QUERY\"\r\n| timechart span=1h count BY record_type",
				"queryParameters": {
					"earliest": "1751371200",
					"latest": "1751479200"
				}
			},
			"name": "Requests by Record Type search"
		},
		"ds_1ZmrypYh": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\"\r\n| timechart span=1h limit=10 usenull=f useother=f count AS Requests by src",
				"queryParameters": {
					"earliest": "1751371200",
					"latest": "1751479200"
				}
			},
			"name": "Column chart search"
		},
		"ds_F7WLfuRN_ds_yE9yBtpa": {
			"type": "ds.search",
			"options": {
				"query": "index=\"sap_logserv_logs\" tag=dns message_type=\"QUERY\"\r\n| fields _time, query\r\n| streamstats current=f last(_time) as last_time by query\r\n| eval gap=last_time - _time\r\n| stats count avg(gap) AS AverageBeaconTime var(gap) AS VarianceBeaconTime BY query\r\n| eval AverageBeaconTime=round(AverageBeaconTime,3), VarianceBeaconTime=round(VarianceBeaconTime,3)\r\n| sort -count\r\n| where VarianceBeaconTime < 60 AND count > 2 AND AverageBeaconTime>1.000\r\n| table  query VarianceBeaconTime  count AverageBeaconTime",
				"queryParameters": {
					"earliest": "1751371200",
					"latest": "1751479200"
				}
			},
			"name": "Bubble chart search copy 1"
		}
	},
	"visualizations": {
		"viz_mEe7x9fI": {
			"type": "splunk.bubble",
			"options": {
				"yAxisAbbreviation": "auto",
				"legendTruncation": "ellipsisMiddle",
				"xAxisLabelRotation": 0,
				"xAxisTitleVisibility": "show",
				"yAxisTitleVisibility": "show",
				"xAxisAbbreviation": "off",
				"xAxisScale": "linear",
				"yAxisScale": "linear",
				"bubbleSizeMax": 56,
				"bubbleSizeMin": 24,
				"legendDisplay": "right",
				"x": "> primary | seriesByName('NumHosts')",
				"y": "> primary | seriesByName('AverageBeaconTime')",
				"size": "> primary | seriesByName('VarianceBeaconTime')",
				"category": "> primary | seriesByName('count')",
				"backgroundColor": "transparent",
				"xAxisTitleText": ""
			},
			"dataSources": {
				"primary": "ds_WaZCTDkV"
			},
			"title": "Hosts to Beaconing Domains"
		},
		"viz_8cdxDtFu": {
