				"xAxisScale": "linear",
				"yAxisScale": "linear",
				"bubbleSizeMax": 50,
				"bubbleSizeMin": 10,
				"bubbleSizeMethod": "area",
				"legendDisplay": "right",
				"x": "> primary | seriesByIndex(1)",
				"y": "> primary | seriesByIndex(2)",
				"size": "> primary | seriesByIndex(3)",
				"category": "> primary | seriesByIndex(0)",
				"backgroundColor": "transparent"
			},
			"dataSources": {
				"primary": "ds_yE9yBtpa"
