				"showSplitSeries": false,
				"showIndependentYRanges": false,
				"legendDisplay": "right",
				"backgroundColor": "transparent"
			},
			"dataSources": {
				"primary": "ds_pYyp9bI7"
			},
			"title": "Requests by Record Type"
		},
		"viz_2nZCdB19": {
			"type": "splunk.column",
			"options": {
				"backgroundColor": "transparent",
